content.content:
1	import AppKit
2	
3	/// A move the runner does not offer, in one sentence (spec §11 TU-8 (2), (6)).
4	struct TutorialRefusal: Error {
5	    let sentence: String
6	}
7	
8	/// How a step was left: its wait met, Next, or Skip.
9	enum TutorialAdvance: String {
10	    case wait, next, skip
11	}
12	
13	/// How a step was entered. A forward entry — start, Next, Skip, a met wait —
14	/// is a trigger; a Back entry is not (spec §11 TU-8 (3)).
15	enum TutorialEntry {
16	    case forward, back
17	}
18	
19	/// What the last Show Me did (spec §11 TU-9).
20	struct TutorialShowMeOutcome {
21	    let step: Int
22	    let ok: Bool
23	    let error: String?
24	    /// Each call's result text, in order.
25	    let results: [String]
26	    /// The files an `export` call was sent to write.
27	    let paths: [String]
28	}
29	
30	/// One tutorial running in one editor window, with no chrome (spec §11
31	/// TU-8): its needs checked at the start, each step's baseline and reveal as
32	/// it begins, its wait read after events, and Back, Skip, Next, Exit and Show
33	/// Me (`TutorialShowMe.swift`, TU-9). The panel that shows it is TU3's; the
34	/// dev tools (`AgentServer+Tutorials.swift`) drive it until then.
35	///
36	/// **Event-driven.** A committed document or view-state change
37	/// (`documentDidChange`, from the editor's `projectDidChange`), a playhead
38	/// move (`trigger`, from `inspectorPlayheadMoved`), a rate change, the
39	/// window's sheet beginning or ending, an export started and a forward step
40	/// entry each call `trigger()`, which schedules ONE coalesced evaluation on
41	/// the next main turn — a documented `DispatchQueue.main.async` seam — so the
42	/// event that met a wait has finished first. Nothing polls. While a Show Me
43	/// runs every evaluation is held, and one runs after its last entry.
44	///
45	/// Owned by `EditorViewController.tutorialRunner`; Exit sets that to nil and
46	/// undoes nothing, and closing the window ends it. Main only.
47	final class TutorialRunner {
48	    let tutorial: Tutorial
49	    weak var editor: EditorViewController?
50	    weak var document: ProjectDocument?
51	
52	    /// The current step's index, 0-based; the last step's once finished.
53	    private(set) var index = 0
54	    private(set) var finished = false
55	    private var baseline: TutorialBaseline
56	    /// `$created` now: the ids added by the latest step, or Show Me call,
57	    /// that added any.
58	    var created: [UInt32] = []
59	    /// `created` as each step began, so Back restores it.
60	    private var createdAtBegin: [Int: [UInt32]] = [:]
61	    private var latches = TutorialLatches()
62	    private var revealRefused: String?
63	    private var completed: [(step: Int, by: TutorialAdvance)] = []
64	    private var evaluationPending = false
65	    private var observers: [NSObjectProtocol] = []
66	
67	    // Show Me's state (`TutorialShowMe.swift`).
68	    /// True from the press until the last entry's answer is back.
69	    var showMeRunning = false
70	    /// A trigger arrived while a Show Me ran.
71	    var heldEvaluation = false
72	    /// The Show Me in flight; its generation drops a stale completion.
73	    var showMeRun: TutorialShowMeRun?
74	    var showMeGeneration = 0
75	    var lastShowMe: TutorialShowMeOutcome?
76	
77	    private init(tutorial: Tutorial, editor: EditorViewController, document: ProjectDocument) {
78	        self.tutorial = tutorial
79	        self.editor = editor
80	        self.document = document
81	        baseline = TutorialBaseline(document: document)
82	    }
83	
84	    @available(*, unavailable) required init?(coder: NSCoder) {
85	        fatalError("TutorialRunner does not support NSCoder")
86	    }
87	
88	    deinit {
89	        for observer in observers { NotificationCenter.default.removeObserver(observer) }
90	    }
91	
92	    // MARK: - Start and exit
93	
94	    /// Starts `tutorial` in `editor`'s window, replacing any running there;
95	    /// refused, starting nothing, when its needs are unmet.
96	    @discardableResult
97	    static func start(_ tutorial: Tutorial, in editor: EditorViewController) throws
98	        -> TutorialRunner {
99	        guard let document = editor.document else {
100	            throw TutorialRefusal(sentence: "This window has no project.")
101	        }
102	        if let sentence = TutorialWait.needsSentence(
103	            tutorial.needs, in: document.editedProject.snapshot)
104	        {
105	            throw TutorialRefusal(sentence: sentence)
106	        }
107	        let runner = TutorialRunner(tutorial: tutorial, editor: editor, document: document)
108	        editor.tutorialRunner = runner
109	        runner.observeSheets(editor.view.window)
110	        runner.begin(0, .forward)
111	        return runner
112	    }
113	
114	    /// Ends the tutorial; the project and its undo history stay as they are.
115	    func exit() {
116	        guard let editor, editor.tutorialRunner === self else { return }
117	        editor.tutorialRunner = nil
118	    }
119	
120	    private func observeSheets(_ window: NSWindow?) {
121	        guard let window else { return }
122	        for name in [NSWindow.willBeginSheetNotification, NSWindow.didEndSheetNotification] {
123	            observers.append(
124	                NotificationCenter.default.addObserver(forName: name, object: window, queue: nil) {
125	                    [weak self] _ in self?.trigger()
126	                })
127	        }
128	    }
129	
130	    // MARK: - Triggers
131	
132	    /// Schedules one evaluation on the next main turn, or holds it while a
133	    /// Show Me runs.
134	    func trigger() {
135	        if showMeRunning {
136	            heldEvaluation = true
137	            return
138	        }
139	        guard !evaluationPending else { return }
140	        evaluationPending = true
141	        DispatchQueue.main.async { [weak self] in self?.evaluate() }
142	    }
143	
144	    /// A committed change or a view-state change; a live tick is ignored.
145	    func documentDidChange(isLive: Bool) {
146	        guard !isLive else { return }
147	        trigger()
148	    }
149	
150	    func playbackRateChanged(_ rate: Float) {
151	        if rate != 0 { latches.playing = true }
152	        trigger()
153	    }
154	
155	    /// The sheet's Export… or Add to Queue, or the `export` tool, started one.
156	    func noteExportStarted() {
157	        latches.exportStarted = true
158	        trigger()
159	    }
160	
161	    private func evaluate() {
162	        evaluationPending = false
163	        if showMeRunning {
164	            heldEvaluation = true
165	            return
166	        }
167	        guard !finished, let editor, editor.tutorialRunner === self, let document else { return }
168	        let step = currentStep
169	        guard !step.wait.isEmpty,
170	              TutorialWait.met(
171	                step.wait, baseline: baseline, created: created, latches: latches,
172	                document: document, window: editor.view.window)
173	        else { return }
174	        advance(by: .wait)
175	    }
176	
177	    // MARK: - Navigation
178	
179	    var currentStep: TutorialStep { tutorial.steps[index] }
180	
181	    /// `$selection`: the step's start selection, in time order.
182	    var selectionAtStart: [UInt32] { baseline.selection }
183	
184	    /// Begins step `next`: its baseline, then its reveal; a forward entry is
185	    /// a trigger.
186	    private func begin(_ next: Int, _ entry: TutorialEntry) {
187	        index = next
188	        finished = false
189	        switch entry {
190	        case .forward: createdAtBegin[next] = created
191	        case .back: created = createdAtBegin[next] ?? created
192	        }
193	        if let document { baseline = TutorialBaseline(document: document) }
194	        latches = TutorialLatches()
195	        revealRefused = nil
196	        if let reveal = currentStep.reveal {
197	            if let inspector = editor?.inspector, inspector.isViewLoaded {
198	                revealRefused = inspector.reveal(reveal)
199	            } else {
200	                revealRefused = "The window has no inspector."
201	            }
202	        }
203	        if entry == .forward { trigger() }
204	    }
205	
206	    private func advance(by how: TutorialAdvance) {
207	        completed.append((index + 1, how))
208	        if let document {
209	            let snapshot = document.editedProject.snapshot
210	            let added = snapshot.clips.map(\.id).filter { !baseline.clipIDs.contains($0) }
211	            if !added.isEmpty { created = TutorialVariables.timeOrdered(added, in: snapshot) }
212	        }
213	        if index + 1 < tutorial.steps.count {
214	            begin(index + 1, .forward)
215	        } else {
216	            finished = true
217	        }
218	    }
219	
220	    private func refuseWhileShowMe() throws {
221	        if showMeRunning { throw TutorialRefusal(sentence: "Show Me is still running.") }
222	    }
223	
224	    func next() throws {
225	        try refuseWhileShowMe()
226	        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
227	        guard currentStep.wait.isEmpty else {
228	            throw TutorialRefusal(
229	                sentence: "This step goes on by itself once it is done; Next is only on a step "
230	                    + "with nothing to wait for.")
231	        }
232	        advance(by: .next)
233	    }
234	
235	    func skip() throws {
236	        try refuseWhileShowMe()
237	        if finished { throw TutorialRefusal(sentence: "The tutorial is finished.") }
238	        guard currentStep.optional else {
239	            throw TutorialRefusal(sentence: "Only an optional step can be skipped.")
240	        }
241	        advance(by: .skip)
242	    }
243	
244	    func back() throws {
245	        try refuseWhileShowMe()
246	        let target: Int
247	        if finished {
248	            target = index
249	        } else {
250	            guard index > 0 else { throw TutorialRefusal(sentence: "This is the first step.") }
251	            target = index - 1
252	        }
253	        completed.removeAll { $0.step >= target + 1 }
254	        begin(target, .back)
255	    }
256	
257	    // MARK: - The state
258	
259	    /// What the panel offers now, in its order.
260	    var offers: [String] {
261	        var out: [String] = []
262	        if finished || index > 0 { out.append("back") }
263	        if !finished {
264	            let step = currentStep
265	            if !step.showMe.isEmpty { out.append("show_me") }
266	            if step.optional { out.append("skip") }
267	            if step.wait.isEmpty { out.append("next") }
268	        }
269	        out.append("exit")
270	        return out
271	    }
272	
273	    /// The dev tools' answer: where the tutorial is and what it holds.
274	    func state() -> [String: Any] {
275	        let step = currentStep
276	        var reveal: Any = NSNull()
277	        if let shown = step.reveal {
278	            reveal = [
279	                "tab": shown.tab.title.lowercased(),
280	                "sub_tab": shown.subTab.map { $0.rawValue as Any } ?? NSNull(),
281	                "section": shown.section.map { $0 as Any } ?? NSNull(),
282	            ] as [String: Any]
283	        }
284	        var last: Any = NSNull()
285	        if let outcome = lastShowMe {
286	            last = [
287	                "step": outcome.step, "ok": outcome.ok,
288	                "error": outcome.error.map { $0 as Any } ?? NSNull(),
289	                "results": outcome.results, "paths": outcome.paths,
290	            ] as [String: Any]
291	        }
292	        return [
293	            "running": true,
294	            "id": tutorial.id,
295	            "title": tutorial.title,
296	            "step": index + 1,
297	            "steps": tutorial.steps.count,
298	            "text": step.text,
299	            "optional": step.optional,
300	            "wait": !step.wait.isEmpty,
301	            "show_me": !step.showMe.isEmpty,
302	            "offers": offers,
303	            "spotlight": step.spotlight.map { $0 as Any } ?? NSNull(),
304	            "reveal": reveal,
305	            "reveal_refused": revealRefused.map { $0 as Any } ?? NSNull(),
306	            "finished": finished,
307	            "show_me_running": showMeRunning,
308	            "last_show_me": last,
309	            "selection_at_start": baseline.selection.map { Int($0) },
310	            "created": created.map { Int($0) },
311	            "completed": completed.map { ["step": $0.step, "by": $0.by.rawValue] as [String: Any] },
312	        ]
313	    }
314	}
