import AppKit

/// What a step began with (spec §11 TU-8 (4)): the selection in time order,
/// every clip id, the range, and the selected clips' JSON for `changed`.
/// Taken from the window's edited project as the step begins. Main only.
struct TutorialBaseline {
    let selection: [UInt32]
    let clipIDs: Set<UInt32>
    let range: (start: Ticks, end: Ticks)?
    /// The clips selected at the start, as the core writes them, by id.
    let selectedClips: [UInt32: [String: Any]]

    init(document: ProjectDocument) {
        let edited = document.editedProject
        let snapshot = edited.snapshot
        let present = Set(snapshot.clips.map(\.id))
        selection = TutorialVariables.timeOrdered(
            Array(document.selection.intersection(present)), in: snapshot)
        clipIDs = present
        range = document.inOutRange
        let clips = TutorialWait.clipJSON(edited)
        var mine: [UInt32: [String: Any]] = [:]
        for id in selection { mine[id] = clips[id] }
        selectedClips = mine
    }
}

/// The latches a step clears as it begins: set by an event, read by a wait.
struct TutorialLatches {
    var exportStarted = false
    var playing = false
}

/// Whether a step's wait is met, and the needs sentence (spec §11 TU-8 (2),
/// (4)). Main only.
enum TutorialWait {
    // MARK: - Evaluation

    /// Whether every condition holds now.
    static func met(
        _ conditions: [TutorialCondition], baseline: TutorialBaseline, created: [UInt32],
        latches: TutorialLatches, document: ProjectDocument, window: NSWindow?
    ) -> Bool {
        guard !conditions.isEmpty else { return false }
        let edited = document.editedProject
        let snapshot = edited.snapshot
        return conditions.allSatisfy { condition in
            switch condition {
            case .selection(let low, let high, let filter):
                let clips = snapshot.clips.filter { document.selection.contains($0.id) }
                guard clips.count >= low, high.map({ clips.count <= $0 }) ?? true else {
                    return false
                }
                return clips.allSatisfy { TutorialClipFacts(clip: $0, in: snapshot).matches(filter) }
            case .changed(let paths):
                let now = clipJSON(edited)
                return baseline.selection.contains { id in
                    guard let before = baseline.selectedClips[id] else { return false }
                    let after = now[id] ?? [:]
                    return paths.contains { path in
                        !value(at: path, in: before).isEqual(value(at: path, in: after))
                    }
                }
            case .clips(let added, let kind):
                let fresh = snapshot.clips.filter {
                    !baseline.clipIDs.contains($0.id) && (kind == nil || $0.source.kindName == kind)
                }
                return fresh.count >= added
            case .playheadInside(let set):
                let ids = set == .selection ? baseline.selection : created
                let playhead = document.playhead
                return ids.contains { id in
                    guard let clip = snapshot.clip(id) else { return false }
                    return clip.start < playhead && playhead < clip.start + clip.duration
                }
            case .rangeSet:
                return document.inOutRange != nil
            case .rangeChanged(let edge):
                let now = document.inOutRange
                let before = baseline.range
                switch edge {
                case .start: return now?.start != before?.start
                case .end: return now?.end != before?.end
                }
            case .sheetExport:
                return window?.attachedSheet?.contentViewController is ExportSheetController
            case .exportStarted:
                return latches.exportStarted
            case .playing:
                return latches.playing
            }
        }
    }

    /// The value at a dotted path of a clip's JSON; absent is `NSNull`.
    static func value(at path: String, in clip: [String: Any]) -> NSObject {
        var here: Any = clip
        for part in path.split(separator: ".") {
            guard let object = here as? [String: Any], let next = object[String(part)] else {
                return NSNull()
            }
            here = next
        }
        return (here as? NSObject) ?? NSNull()
    }

    /// The last handle read and its clips by id: `changed` reads one handle
    /// many times between edits.
    private static var parsed: (handle: ReelProject, clips: [UInt32: [String: Any]])?

    /// The project's `clips`, as the core writes them, by id. Main only.
    static func clipJSON(_ project: ReelProject) -> [UInt32: [String: Any]] {
        if let parsed, parsed.handle === project { return parsed.clips }
        var clips: [UInt32: [String: Any]] = [:]
        if let top = (try? JSONSerialization.jsonObject(with: Data(project.json.utf8)))
            as? [String: Any], let list = top["clips"] as? [[String: Any]]
        {
            for clip in list {
                if let id = (clip["id"] as? NSNumber)?.uint32Value { clips[id] = clip }
            }
        }
        parsed = (project, clips)
        return clips
    }

    // MARK: - Needs

    /// nil when some clip meets the tutorial's `needs.clip` (or it needs
    /// none); else the one sentence saying what is missing.
    static func needsSentence(_ needs: [String: Any]?, in snapshot: ProjectSnapshot) -> String? {
        guard let needs else { return nil }
        if snapshot.clips.contains(where: { TutorialClipFacts(clip: $0, in: snapshot).matches(needs) }) {
            return nil
        }
        var noun = "a clip"
        if let kind = needs["kind"] as? String {
            let article = ["a", "e", "i", "o", "u"].contains(kind.prefix(1)) ? "an" : "a"
            noun = "\(article) \(kind) clip"
        }
        let phrases: [String: (yes: String, no: String)] = [
            "has_sound": ("has sound", "has no sound"),
            "has_pixels": ("has a picture", "has no picture"),
            "follows_clip": (
                "meets the clip before it on its track",
                "does not meet the clip before it on its track"
            ),
            "has_transition": ("has a transition in", "has no transition in"),
        ]
        let predicates: [String] = TutorialClipFacts.keys.compactMap { key in
            guard let phrase = phrases[key], let wanted = needs[key] as? Bool else { return nil }
            return wanted ? phrase.yes : phrase.no
        }
        var sentence = "This tutorial needs " + noun
        if !predicates.isEmpty { sentence += " that " + joined(predicates) }
        return sentence + "."
    }

    /// `p`, `p1 and p2`, `p1, p2 and p3`.
    static func joined(_ parts: [String]) -> String {
        guard let last = parts.last else { return "" }
        guard parts.count > 1 else { return last }
        return parts.dropLast().joined(separator: ", ") + " and " + last
    }
}

