3	/// TU-2 (9)'s variables, resolved for one Show Me call (spec §11 TU-8 (5)):
4	/// `$selection` is the step's start selection, `$created` the ids the latest
5	/// earlier step or earlier call of this Show Me added, `$playhead` the tick
6	/// now, `$pick` the first matching clip in time order, `$first` the earliest
7	/// of a set, `$time` a tick on a set's span (`middle` snapped to the frame)
8	/// and `$track` the front track when the call is made. Time order is by
9	/// start, ties front track first (`tracks.last` is the front).
10	enum TutorialVariables {
11	    static func resolve(
12	        _ value: Any, selection: [UInt32], created: [UInt32], snapshot: ProjectSnapshot,
13	        playhead: Ticks
14	    ) throws -> Any {
15	        let context = Context(
16	            selection: selection, created: created, snapshot: snapshot, playhead: playhead)
17	        return try context.resolve(value)
18	    }
19	
20	    /// `ids` in time order: start, then the front track first, then id.
21	    static func timeOrdered(_ ids: [UInt32], in snapshot: ProjectSnapshot) -> [UInt32] {
22	        timeOrdered(snapshot.clips.filter { ids.contains($0.id) }, in: snapshot).map(\.id)
23	    }
24	
25	    static func timeOrdered(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot)
26	        -> [ClipSnapshot] {
27	        let depth = Dictionary(
28	            uniqueKeysWithValues: snapshot.tracks.enumerated().map { ($1.id, $0) })
29	        return clips.sorted { lhs, rhs in
30	            if lhs.start != rhs.start { return lhs.start < rhs.start }
31	            let left = depth[lhs.track] ?? -1
32	            let right = depth[rhs.track] ?? -1
33	            if left != right { return left > right }
34	            return lhs.id < rhs.id
35	        }
36	    }
37	
38	    private struct Context {
39	        let selection: [UInt32]
40	        let created: [UInt32]
41	        let snapshot: ProjectSnapshot
42	        let playhead: Ticks
43	
44	        func resolve(_ value: Any) throws -> Any {
45	            if let text = value as? String {
46	                switch text {
47	                case "$selection": return selection.map { Int($0) }
48	                case "$created": return created.map { Int($0) }
49	                case "$playhead": return playhead
50	                default: return text
51	                }
52	            }
53	            if let list = value as? [Any] { return try list.map(resolve) }
54	            if let object = value as? [String: Any] {
55	                if object.count == 1, let (key, item) = object.first, key.hasPrefix("$") {
56	                    return try variable(key, item)
57	                }
58	                var out: [String: Any] = [:]
59	                for (key, item) in object { out[key] = try resolve(item) }
60	                return out
61	            }
62	            return value
63	        }
64	
65	        func variable(_ key: String, _ item: Any) throws -> Any {
66	            switch key {
67	            case "$pick", "$first":
68	                guard let id = try reference([key: item]).first else {
69	                    throw TutorialRefusal(sentence: "No clip in the project is the one Show Me picks.")
70	                }
71	                return Int(id)
72	            case "$track":
73	                guard let front = snapshot.tracks.last else {
74	                    throw TutorialRefusal(sentence: "The project has no track.")
75	                }
76	                return Int(front.id)
77	            case "$time":
78	                guard let spec = item as? [String: Any], let of = spec["of"],
79	                      let at = spec["at"] as? String
80	                else { throw TutorialRefusal(sentence: "Show Me's $time is not {of, at}.") }
81	                let clips = try reference(of).compactMap { snapshot.clip($0) }
82	                guard let start = clips.map(\.start).min(),
83	                      let end = clips.map({ $0.start + $0.duration }).max()
84	                else {
85	                    throw TutorialRefusal(sentence: "Show Me's time names no clip in the project.")
86	                }
87	                switch at {
88	                case "start": return start
89	                case "end": return end
90	                default: return ReelTime.snapToFrame(start + (end - start) / 2, fps: snapshot.canvas.fps)
91	                }
92	            default:
93	                throw TutorialRefusal(sentence: "Show Me names an unknown variable \(key).")
94	            }
95	        }
96	
97	        /// A reference's ids in time order: a set, a `$pick`'s one clip or a
98	        /// `$first`'s.
99	        func reference(_ value: Any) throws -> [UInt32] {
100	            if let text = value as? String {
101	                switch text {
102	                case "$selection": return TutorialVariables.timeOrdered(selection, in: snapshot)
103	                case "$created": return TutorialVariables.timeOrdered(created, in: snapshot)
104	                default: break
105	                }
106	            } else if let object = value as? [String: Any], object.count == 1 {
107	                if let filter = object["$pick"] as? [String: Any] {
108	                    let ordered = TutorialVariables.timeOrdered(snapshot.clips, in: snapshot)
109	                    let hit = ordered.first {
110	                        TutorialClipFacts(clip: $0, in: snapshot).matches(filter)
111	                    }
112	                    return hit.map { [$0.id] } ?? []
113	                }
114	                if let set = object["$first"] {
115	                    return try reference(set).prefix(1).map { $0 }
116	                }
117	            }
118	            throw TutorialRefusal(sentence: "Show Me names a clip set that is not one.")
119	        }
120	    }
121	}
