import Foundation

/// TU-2 (9)'s variables, resolved for one Show Me call (spec §11 TU-8 (5)):
/// `$selection` is the step's start selection, `$created` the ids the latest
/// earlier step or earlier call of this Show Me added, `$playhead` the tick
/// now, `$pick` the first matching clip in time order, `$first` the earliest
/// of a set, `$time` a tick on a set's span (`middle` snapped to the frame)
/// and `$track` the front track when the call is made. Time order is by
/// start, ties front track first (`tracks.last` is the front).
enum TutorialVariables {
    static func resolve(
        _ value: Any, selection: [UInt32], created: [UInt32], snapshot: ProjectSnapshot,
        playhead: Ticks
    ) throws -> Any {
        let context = Context(
            selection: selection, created: created, snapshot: snapshot, playhead: playhead)
        return try context.resolve(value)
    }

    /// `ids` in time order: start, then the front track first, then id.
    static func timeOrdered(_ ids: [UInt32], in snapshot: ProjectSnapshot) -> [UInt32] {
        timeOrdered(snapshot.clips.filter { ids.contains($0.id) }, in: snapshot).map(\.id)
    }

    static func timeOrdered(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot)
        -> [ClipSnapshot] {
        let depth = Dictionary(
            uniqueKeysWithValues: snapshot.tracks.enumerated().map { ($1.id, $0) })
        return clips.sorted { lhs, rhs in
            if lhs.start != rhs.start { return lhs.start < rhs.start }
            let left = depth[lhs.track] ?? -1
            let right = depth[rhs.track] ?? -1
            if left != right { return left > right }
            return lhs.id < rhs.id
        }
    }

    private struct Context {
        let selection: [UInt32]
        let created: [UInt32]
        let snapshot: ProjectSnapshot
        let playhead: Ticks

        func resolve(_ value: Any) throws -> Any {
            if let text = value as? String {
                switch text {
                case "$selection": return selection.map { Int($0) }
                case "$created": return created.map { Int($0) }
                case "$playhead": return playhead
                default: return text
                }
            }
            if let list = value as? [Any] { return try list.map(resolve) }
            if let object = value as? [String: Any] {
                if object.count == 1, let (key, item) = object.first, key.hasPrefix("$") {
                    return try variable(key, item)
                }
                var out: [String: Any] = [:]
                for (key, item) in object { out[key] = try resolve(item) }
                return out
            }
            return value
        }

        func variable(_ key: String, _ item: Any) throws -> Any {
            switch key {
            case "$pick", "$first":
                guard let id = try reference([key: item]).first else {
                    throw TutorialRefusal(sentence: "No clip in the project is the one Show Me picks.")
                }
                return Int(id)
            case "$track":
                guard let front = snapshot.tracks.last else {
                    throw TutorialRefusal(sentence: "The project has no track.")
                }
                return Int(front.id)
            case "$time":
                guard let spec = item as? [String: Any], let of = spec["of"],
                      let at = spec["at"] as? String
                else { throw TutorialRefusal(sentence: "Show Me's $time is not {of, at}.") }
                let clips = try reference(of).compactMap { snapshot.clip($0) }
                guard let start = clips.map(\.start).min(),
                      let end = clips.map({ $0.start + $0.duration }).max()
                else {
                    throw TutorialRefusal(sentence: "Show Me's time names no clip in the project.")
                }
                switch at {
                case "start": return start
                case "end": return end
                default: return ReelTime.snapToFrame(start + (end - start) / 2, fps: snapshot.canvas.fps)
                }
            default:
                throw TutorialRefusal(sentence: "Show Me names an unknown variable \(key).")
            }
        }

        /// A reference's ids in time order: a set, a `$pick`'s one clip or a
        /// `$first`'s.
        func reference(_ value: Any) throws -> [UInt32] {
            if let text = value as? String {
                switch text {
                case "$selection": return TutorialVariables.timeOrdered(selection, in: snapshot)
                case "$created": return TutorialVariables.timeOrdered(created, in: snapshot)
                default: break
                }
            } else if let object = value as? [String: Any], object.count == 1 {
                if let filter = object["$pick"] as? [String: Any] {
                    let ordered = TutorialVariables.timeOrdered(snapshot.clips, in: snapshot)
                    let hit = ordered.first {
                        TutorialClipFacts(clip: $0, in: snapshot).matches(filter)
                    }
                    return hit.map { [$0.id] } ?? []
                }
                if let set = object["$first"] {
                    return try reference(set).prefix(1).map { $0 }
                }
            }
            throw TutorialRefusal(sentence: "Show Me names a clip set that is not one.")
        }
    }
}

