3	/// What a step began with (spec §11 TU-8 (4)): the selection in time order,
4	/// every clip id, the range, and the selected clips' JSON for `changed`.
5	/// Taken from the window's edited project as the step begins. Main only.
6	struct TutorialBaseline {
7	    let selection: [UInt32]
8	    let clipIDs: Set<UInt32>
9	    let range: (start: Ticks, end: Ticks)?
10	    /// The clips selected at the start, as the core writes them, by id.
11	    let selectedClips: [UInt32: [String: Any]]
12	
13	    init(document: ProjectDocument) {
14	        let edited = document.editedProject
15	        let snapshot = edited.snapshot
16	        let present = Set(snapshot.clips.map(\.id))
17	        selection = TutorialVariables.timeOrdered(
18	            Array(document.selection.intersection(present)), in: snapshot)
19	        clipIDs = present
20	        range = document.inOutRange
21	        let clips = TutorialWait.clipJSON(edited)
22	        var mine: [UInt32: [String: Any]] = [:]
23	        for id in selection { mine[id] = clips[id] }
24	        selectedClips = mine
25	    }
26	}
27	
28	/// The latches a step clears as it begins: set by an event, read by a wait.
29	struct TutorialLatches {
30	    var exportStarted = false
31	    var playing = false
32	}
33	
34	/// Whether a step's wait is met, and the needs sentence (spec §11 TU-8 (2),
35	/// (4)). Main only.
36	enum TutorialWait {
37	    // MARK: - Evaluation
38	
39	    /// Whether every condition holds now.
40	    static func met(
41	        _ conditions: [TutorialCondition], baseline: TutorialBaseline, created: [UInt32],
42	        latches: TutorialLatches, document: ProjectDocument, window: NSWindow?
43	    ) -> Bool {
44	        guard !conditions.isEmpty else { return false }
45	        let edited = document.editedProject
46	        let snapshot = edited.snapshot
47	        return conditions.allSatisfy { condition in
48	            switch condition {
49	            case .selection(let low, let high, let filter):
50	                let clips = snapshot.clips.filter { document.selection.contains($0.id) }
51	                guard clips.count >= low, high.map({ clips.count <= $0 }) ?? true else {
52	                    return false
53	                }
54	                return clips.allSatisfy { TutorialClipFacts(clip: $0, in: snapshot).matches(filter) }
55	            case .changed(let paths):
56	                let now = clipJSON(edited)
57	                return baseline.selection.contains { id in
58	                    guard let before = baseline.selectedClips[id] else { return false }
59	                    let after = now[id] ?? [:]
60	                    return paths.contains { path in
61	                        !value(at: path, in: before).isEqual(value(at: path, in: after))
62	                    }
63	                }
64	            case .clips(let added, let kind):
65	                let fresh = snapshot.clips.filter {
66	                    !baseline.clipIDs.contains($0.id) && (kind == nil || $0.source.kindName == kind)
67	                }
68	                return fresh.count >= added
69	            case .playheadInside(let set):
70	                let ids = set == .selection ? baseline.selection : created
71	                let playhead = document.playhead
72	                return ids.contains { id in
73	                    guard let clip = snapshot.clip(id) else { return false }
74	                    return clip.start < playhead && playhead < clip.start + clip.duration
75	                }
76	            case .rangeSet:
77	                return document.inOutRange != nil
78	            case .rangeChanged(let edge):
79	                let now = document.inOutRange
80	                let before = baseline.range
81	                switch edge {
82	                case .start: return now?.start != before?.start
83	                case .end: return now?.end != before?.end
84	                }
85	            case .sheetExport:
86	                return window?.attachedSheet?.contentViewController is ExportSheetController
87	            case .exportStarted:
88	                return latches.exportStarted
89	            case .playing:
90	                return latches.playing
91	            }
92	        }
93	    }
94	
95	    /// The value at a dotted path of a clip's JSON; absent is `NSNull`.
96	    static func value(at path: String, in clip: [String: Any]) -> NSObject {
97	        var here: Any = clip
98	        for part in path.split(separator: ".") {
99	            guard let object = here as? [String: Any], let next = object[String(part)] else {
100	                return NSNull()
101	            }
102	            here = next
103	        }
104	        return (here as? NSObject) ?? NSNull()
105	    }
106	
107	    /// The last handle read and its clips by id: `changed` reads one handle
108	    /// many times between edits.
109	    private static var parsed: (handle: ReelProject, clips: [UInt32: [String: Any]])?
110	
111	    /// The project's `clips`, as the core writes them, by id. Main only.
112	    static func clipJSON(_ project: ReelProject) -> [UInt32: [String: Any]] {
113	        if let parsed, parsed.handle === project { return parsed.clips }
114	        var clips: [UInt32: [String: Any]] = [:]
115	        if let top = (try? JSONSerialization.jsonObject(with: Data(project.json.utf8)))
116	            as? [String: Any], let list = top["clips"] as? [[String: Any]]
117	        {
118	            for clip in list {
119	                if let id = (clip["id"] as? NSNumber)?.uint32Value { clips[id] = clip }
120	            }
121	        }
122	        parsed = (project, clips)
123	        return clips
124	    }
125	
126	    // MARK: - Needs
127	
128	    /// nil when some clip meets the tutorial's `needs.clip` (or it needs
129	    /// none); else the one sentence saying what is missing.
130	    static func needsSentence(_ needs: [String: Any]?, in snapshot: ProjectSnapshot) -> String? {
131	        guard let needs else { return nil }
132	        if snapshot.clips.contains(where: { TutorialClipFacts(clip: $0, in: snapshot).matches(needs) }) {
133	            return nil
134	        }
135	        var noun = "a clip"
136	        if let kind = needs["kind"] as? String {
137	            let article = ["a", "e", "i", "o", "u"].contains(kind.prefix(1)) ? "an" : "a"
138	            noun = "\(article) \(kind) clip"
139	        }
140	        let phrases: [String: (yes: String, no: String)] = [
141	            "has_sound": ("has sound", "has no sound"),
142	            "has_pixels": ("has a picture", "has no picture"),
143	            "follows_clip": (
144	                "meets the clip before it on its track",
145	                "does not meet the clip before it on its track"
146	            ),
147	            "has_transition": ("has a transition in", "has no transition in"),
148	        ]
149	        let predicates: [String] = TutorialClipFacts.keys.compactMap { key in
150	            guard let phrase = phrases[key], let wanted = needs[key] as? Bool else { return nil }
151	            return wanted ? phrase.yes : phrase.no
152	        }
153	        var sentence = "This tutorial needs " + noun
154	        if !predicates.isEmpty { sentence += " that " + joined(predicates) }
155	        return sentence + "."
156	    }
157	
158	    /// `p`, `p1 and p2`, `p1, p2 and p3`.
159	    static func joined(_ parts: [String]) -> String {
160	        guard let last = parts.last else { return "" }
161	        guard parts.count > 1 else { return last }
162	        return parts.dropLast().joined(separator: ", ") + " and " + last
163	    }
164	}
