1	import AppKit
2	
3	/// The inspector reached by name from outside it: the pane it shows, a
4	/// section scrolled to the top, the Clip pane, and a tutorial step's reveal
5	/// (spec §11 TU-8 (6)). `shownPane`, `scroll(to:)` and `clipPane` were
6	/// `select_inspector_tab`'s (`AgentServer+InspectorTab.swift`), moved here
7	/// whole so the runner, which is product code, can reach them. Main only.
8	extension InspectorViewController {
9	    /// The scroll view the inspector shows its pane in, and that pane.
10	    func shownPane() -> (NSScrollView, InspectorPaneView)? {
11	        var queue: [NSView] = [view]
12	        while !queue.isEmpty {
13	            let view = queue.removeFirst()
14	            if let scroll = view as? NSScrollView, let pane = scroll.documentView as? InspectorPaneView {
15	                return (scroll, pane)
16	            }
17	            queue.append(contentsOf: view.subviews)
18	        }
19	        return nil
20	    }
21	
22	    /// Scrolls the shown pane so section `id`'s top is the visible top,
23	    /// clamped to the pane; refused, naming the sections it holds, when it
24	    /// holds no such section. Writes no preference and opens nothing.
25	    func scroll(to id: String) throws {
26	        let shown = shownPane()
27	        let sections = shown?.1.sections ?? []
28	        guard let (scroll, pane) = shown, let section = sections.first(where: { $0.id == id })
29	        else {
30	            let ids = sections.map(\.id)
31	            throw AgentServer.ToolError(
32	                message: "The shown pane has no section \(id); its sections are "
33	                    + (ids.isEmpty ? "none" : ids.joined(separator: ", ")) + ".")
34	        }
35	        view.layoutSubtreeIfNeeded()
36	        let clip = scroll.contentView
37	        let top = section.convert(section.bounds, to: pane).minY
38	        let bottom = max(0, pane.frame.height - clip.bounds.height)
39	        clip.scroll(to: NSPoint(x: 0, y: min(max(0, top), bottom)))
40	        scroll.reflectScrolledClipView(clip)
41	    }
42	
43	    /// The Clip pane among the inspector's descendants — there only while the
44	    /// Clip tab shows it.
45	    func clipPane() -> ClipPane? {
46	        var queue: [NSView] = [view]
47	        while !queue.isEmpty {
48	            let view = queue.removeFirst()
49	            if let pane = view as? ClipPane { return pane }
50	            queue.append(contentsOf: view.subviews)
51	        }
52	        return nil
53	    }
54	
55	    /// A tutorial step's reveal through the clicks' own paths: the tab, the
56	    /// sub-tab when the selection offers it, the section opened by
57	    /// `InspectorSection.reveal()` (which writes no preference), then
58	    /// scrolled to the top. nil, or the sentence saying what could not be
59	    /// shown.
60	    func reveal(_ r: TutorialReveal) -> String? {
61	        select(r.tab)
62	        if let sub = r.subTab {
63	            let offered = clipPane()?.subTabs ?? []
64	            guard !selectedClips.isEmpty, offered.contains(sub) else {
65	                return "The selection has no \(sub.title) sub-tab."
66	            }
67	            selectClipSubTab(sub)
68	        }
69	        guard let id = r.section else { return nil }
70	        guard let section = shownPane()?.1.sections.first(where: { $0.id == id }) else {
71	            return "The inspector shows no \(id) section now."
72	        }
73	        section.reveal()
74	        do {
75	            try scroll(to: id)
76	        } catch let error as AgentServer.ToolError {
77	            return error.message
78	        } catch {
79	            return error.localizedDescription
80	        }
81	        return nil
82	    }
83	
84	    /// The shown pane's sections whose frame meets the visible rect, top to
85	    /// bottom.
86	    func visibleSectionIDs() -> [String] {
87	        guard let (_, pane) = shownPane() else { return [] }
88	        view.layoutSubtreeIfNeeded()
89	        let visible = pane.visibleRect
90	        return pane.sections.filter { section in
91	            let frame = section.convert(section.bounds, to: pane)
92	            return frame.height > 0 && frame.intersects(visible)
93	        }.map(\.id)
94	    }
95	
96	    /// The shown pane's open sections, top to bottom.
97	    func expandedSectionIDs() -> [String] {
98	        (shownPane()?.1.sections ?? []).filter(\.isExpanded).map(\.id)
99	    }
100	}
