135	
136	    func tutorialStartTool() -> [String: Any] {
137	        tool(
138	            "tutorial_start",
139	            "DEV TOOL (absent from Distribution builds). Start a guide tutorial by id in a "
140	                + "project's editor window, replacing any tutorial running there: its needs are "
141	                + "checked first and, when no clip meets them, the call is refused with the "
142	                + "sentence naming what is missing. Answers the runner's state at step 1: ok, "
143	                + "project, running and, while running, id, title, step (1-based), steps, text, "
144	                + "optional, wait, show_me, offers (of back, show_me, skip, next, exit), "
145	                + "spotlight, reveal {tab, sub_tab, section} or null, reveal_refused, finished, "
146	                + "show_me_running, last_show_me {step, ok, error, results, paths} or null, "
147	                + "selection_at_start, created and completed [{step, by}]. A wait already met "
148	                + "advances on a later main turn. Refused: an unknown id (the refusal lists the "
149	                + "tutorials), a tutorial the model does not read (with its reason) and a project "
150	                + "with no window.",
151	            [
152	                "id": [
153	                    "type": "string",
154	                    "description": "The tutorial's id, as its guide page names it "
155	                        + "(audio.volume, editing.split, …).",
156	                ]
157	            ],
158	            required: ["id"])
159	    }
160	
161	    func tutorialStateTool() -> [String: Any] {
162	        tool(
163	            "tutorial_state",
164	            "DEV TOOL (absent from Distribution builds). Answer the state of the tutorial "
165	                + "running in a project's editor window, changing nothing: running false when "
166	                + "none runs, else the fields tutorial_start answers.",
167	            [:])
168	    }
169	
170	    func tutorialStepTool() -> [String: Any] {
171	        tool(
172	            "tutorial_step",
173	            "DEV TOOL (absent from Distribution builds). Press one of the running tutorial's "
174	                + "buttons: show_me runs the step's Show Me — its tool calls through the "
175	                + "assistant's lane with ordinary undo, its menu items through the menu bar's "
176	                + "own validated item — and answers once it has finished (up to 60 s), its "
177	                + "outcome in last_show_me; next goes on from a step with no wait; back re-begins "
178	                + "the step before (or the last, once finished) and does not evaluate it; skip "
179	                + "passes an optional step. Answers the state. Refused in the runner's own "
180	                + "sentence: a move the step does not offer, and no tutorial running.",
181	            [
182	                "action": [
183	                    "type": "string", "enum": ["show_me", "next", "back", "skip"],
184	                    "description": "The button: show_me, next, back or skip.",
185	                ]
186	            ],
187	            required: ["action"])
188	    }
189	
190	    func tutorialExitTool() -> [String: Any] {
191	        tool(
192	            "tutorial_exit",
193	            "DEV TOOL (absent from Distribution builds). End the tutorial running in a "
194	                + "project's editor window, undoing nothing. Answers the state (running false). "
195	                + "Refused when no tutorial runs there.",
196	            [:])
197	    }
