1	import Foundation
2	
3	/// The tutorials the app runs (spec §11 TU-8 (1)): `Tutorials.json`, which
4	/// the build's "Write Tutorials" step writes with
5	/// `tools/tutorials/tutorial_extract.py`, read into typed tutorials and steps.
6	///
7	/// **Strict, per tutorial.** Anything outside TU-2 (2)–(9) — a key at any
8	/// level, a type, a value, a `reveal` whose section lives elsewhere, a
9	/// spotlight the target table lacks, a `$`-string no variable spells — refuses
10	/// THAT tutorial into `refused` with the reason, and the rest of the file
11	/// still reads. Only the top level throws. `tutorial_check.py` holds this
12	/// decoder to its own checker both ways through `tutorial_probe.swift`, so it
13	/// refuses nothing the checker accepts and accepts nothing it refuses. The
14	/// catalog, menu-bar, inventory and fixture-path checks are the checker's
15	/// alone (build time); one failing at run time is a refused Show Me.
16	enum TutorialJSON {
17	    /// A JSON `true`/`false` — not an `NSNumber` 0 or 1, which `as? Bool` takes.
18	    static func isBool(_ v: Any) -> Bool {
19	        guard let number = v as? NSNumber else { return false }
20	        return CFGetTypeID(number as CFTypeRef) == CFBooleanGetTypeID()
21	    }
22	
23	    /// A JSON integer: a number that is not a boolean and has no fraction.
24	    static func isInt(_ v: Any) -> Bool {
25	        guard let number = v as? NSNumber, !isBool(v) else { return false }
26	        let value = number.doubleValue
27	        return value.isFinite && value == value.rounded() && abs(value) < 9.0e15
28	    }
29	}
30	
31	struct TutorialModelError: LocalizedError {
32	    let message: String
33	    var errorDescription: String? { message }
34	}
35	
36	struct TutorialLibrary {
37	    let pages: [TutorialPage]
38	    /// Tutorial id → the model's reason for refusing it.
39	    let refused: [String: String]
40	
41	    /// Throws on the top level only: not an object, `format` not 1, `pages`
42	    /// not a list of pages.
43	    static func decode(_ data: Data) throws -> TutorialLibrary {
44	        guard let top = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] else {
45	            throw TutorialModelError(message: "Tutorials.json is not a JSON object.")
46	        }
47	        guard let format = top["format"], TutorialJSON.isInt(format),
48	              (format as? NSNumber)?.intValue == 1
49	        else {
50	            throw TutorialModelError(message: "Tutorials.json's format is not 1.")
51	        }
52	        guard let rawPages = top["pages"] as? [Any] else {
53	            throw TutorialModelError(message: "Tutorials.json's pages is not a list.")
54	        }
55	        var pages: [TutorialPage] = []
56	        var refused: [String: String] = [:]
57	        for (index, raw) in rawPages.enumerated() {
58	            guard let page = raw as? [String: Any], let name = page["page"] as? String,
59	                  let title = page["title"] as? String, let list = page["tutorials"] as? [Any]
60	            else {
61	                throw TutorialModelError(
62	                    message: "Tutorials.json's page \(index + 1) is not {page, title, tutorials}.")
63	            }
64	            var tutorials: [Tutorial] = []
65	            for (number, entry) in list.enumerated() {
66	                let fallback = "\(name) tutorial \(number + 1)"
67	                let id = ((entry as? [String: Any])?["id"] as? String) ?? fallback
68	                do {
69	                    tutorials.append(try TutorialDecoder.tutorial(entry))
70	                } catch let error as TutorialModelError {
71	                    refused[id] = error.message
72	                }
73	            }
74	            pages.append(TutorialPage(page: name, title: title, tutorials: tutorials))
75	        }
76	        return TutorialLibrary(pages: pages, refused: refused)
77	    }
78	
79	    private static var memo: TutorialLibrary?
80	
81	    /// The bundle's `Tutorials.json`, read once. Main only.
82	    static func bundled() throws -> TutorialLibrary {
83	        if let memo { return memo }
84	        guard let url = Bundle.main.url(forResource: "Tutorials", withExtension: "json") else {
85	            throw TutorialModelError(message: "The app has no Tutorials.json.")
86	        }
87	        let library = try decode(try Data(contentsOf: url))
88	        memo = library
89	        return library
90	    }
91	
