39	            do {
40	                steps.append(try step(raw))
41	            } catch let error as TutorialModelError {
42	                throw refuse("step \(index + 1): \(error.message)")
43	            }
44	        }
45	        return Tutorial(id: id, title: title, anchor: anchor, needs: needs, steps: steps)
46	    }
47	
48	    static func step(_ raw: Any) throws -> TutorialStep {
49	        guard let object = raw as? [String: Any] else { throw refuse("the step is not an object") }
50	        if let stranger = object.keys.sorted().first(where: { !stepKeys.contains($0) }) {
51	            throw refuse("unknown step key \(stranger)")
52	        }
53	        guard let text = object["text"] as? String, !text.isEmpty else {
54	            throw refuse("the step has no sentence")
55	        }
56	        let reveal = try object["reveal"].map(Self.reveal)
57	        var spotlight: String?
58	        if let raw = object["spotlight"] { spotlight = try Self.spotlight(raw) }
59	        var wait: [TutorialCondition] = []
60	        if let raw = object["wait"] { wait = try Self.wait(raw) }
61	        var showMe: [TutorialShowMe] = []
62	        if let raw = object["show_me"] {
63	            let entries = (raw as? [Any]) ?? [raw]
64	            guard !entries.isEmpty else { throw refuse("show_me is an empty list") }
65	            showMe = try entries.map(Self.showMe)
66	        }
67	        var optional = false
68	        if let raw = object["optional"] {
69	            guard TutorialJSON.isBool(raw), (raw as? Bool) == true else {
70	                throw refuse("optional is not true")
71	            }
