79	    /// A clip filter (TU-2 (3)), less any `extra` keys.
80	    static func filter(_ raw: Any, _ where_: String, extra: Set<String> = []) throws
81	        -> [String: Any] {
82	        guard let object = raw as? [String: Any] else { throw refuse("\(where_) is not an object") }
83	        var out: [String: Any] = [:]
84	        for key in object.keys.sorted() where !extra.contains(key) {
85	            guard let value = object[key] else { continue }
