87	                throw refuse("\(where_) has an unknown key \(key)")
88	            }
89	            if key == "kind" {
90	                guard let kind = value as? String, TutorialClipFacts.kinds.contains(kind) else {
91	                    throw refuse("\(where_)'s kind is not a clip kind")
92	                }
93	            } else if !TutorialJSON.isBool(value) {
94	                throw refuse("\(where_)'s \(key) is not a boolean")
95	            }
96	            out[key] = value
97	        }
98	        return out
99	    }
100	
101	    static func reveal(_ raw: Any) throws -> TutorialReveal {
102	        guard let object = raw as? [String: Any], let tabName = object["tab"] as? String,
103	              Set(object.keys).isSubset(of: ["tab", "sub_tab", "section"])
104	        else { throw refuse("reveal is {tab, sub_tab?, section?}") }
105	        guard let tab = InspectorTab.allCases.first(where: { $0.title.lowercased() == tabName })
106	        else { throw refuse("reveal.tab \(tabName) is not an inspector tab") }
107	        var subTab: ClipSubTab?
108	        if let raw = object["sub_tab"] {
109	            guard tab == .clip, let name = raw as? String, let found = ClipSubTab(rawValue: name)
110	            else { throw refuse("reveal.sub_tab is not a Clip tab sub-tab") }
111	            subTab = found
112	        }
113	        var section: String?
114	        if let raw = object["section"] {
115	            guard let id = raw as? String, let home = TutorialTargets.sections[id] else {
116	                throw refuse("reveal.section is not in the target table")
117	            }
118	            guard home == TutorialSectionHome(tab: tab, subTab: subTab) else {
