126	    static func spotlight(_ raw: Any) throws -> String {
127	        guard let name = raw as? String else { throw refuse("spotlight is not a string") }
128	        if TutorialTargets.fixed[name] != nil { return name }
129	        if name.hasPrefix(TutorialTargets.sectionPrefix),
130	           TutorialTargets.sections[String(name.dropFirst(TutorialTargets.sectionPrefix.count))]
131	            != nil
132	        {
133	            return name
134	        }
135	        if name.hasPrefix(TutorialTargets.clipPrefix),
136	           TutorialTargets.clipRefs.contains(String(name.dropFirst(TutorialTargets.clipPrefix.count)))
