152	    static func condition(_ key: String, _ value: Any) throws -> TutorialCondition {
153	        func isTrue(_ v: Any) -> Bool { TutorialJSON.isBool(v) && (v as? Bool) == true }
154	        switch key {
155	        case "selection":
156	            let filter = try Self.filter(value, "wait.selection", extra: ["min", "max"])
