158	            var low = 1
159	            if let raw = object["min"] {
160	                guard TutorialJSON.isInt(raw), let n = (raw as? NSNumber)?.intValue, n >= 0 else {
161	                    throw refuse("wait.selection.min is not an integer ≥ 0")
162	                }
