170	                high = n
171	            }
172	            return .selection(min: low, max: high, filter: filter)
173	        case "changed":
174	            let paths = (value as? String).map { [$0] } ?? (value as? [Any])?.compactMap { $0 as? String }
175	            guard let paths, !paths.isEmpty, paths.count == ((value as? [Any])?.count ?? 1),
176	                  paths.allSatisfy({ !$0.isEmpty })
177	            else { throw refuse("wait.changed is not a path or a list of paths") }
178	            return .changed(paths)
179	        case "clips":
