181	                  Set(object.keys).isSubset(of: ["added", "kind"]),
182	                  let added = object["added"], TutorialJSON.isInt(added),
183	                  let count = (added as? NSNumber)?.intValue, count >= 1
184	            else { throw refuse("wait.clips is {added: int ≥ 1, kind?}") }
185	            var kind: String?
186	            if let raw = object["kind"] {
187	                guard let name = raw as? String, TutorialClipFacts.kinds.contains(name) else {
188	                    throw refuse("wait.clips.kind is not a clip kind")
189	                }
190	                kind = name
191	            }
192	            return .clips(added: count, kind: kind)
193	        case "playhead":
