195	                  let raw = object["inside"] as? String, let set = TutorialClipSet(rawValue: raw)
196	            else { throw refuse("wait.playhead is {inside: \"$selection\"|\"$created\"}") }
197	            return .playheadInside(set)
198	        case "range":
199	            if let object = value as? [String: Any], object.count == 1 {
200	                if let set = object["set"], isTrue(set) { return .rangeSet }
201	                if let raw = object["changed"] as? String, let edge = TutorialRangeEdge(rawValue: raw) {
202	                    return .rangeChanged(edge)
203	                }
204	            }
205	            throw refuse("wait.range is {set: true} or {changed: \"start\"|\"end\"}")
206	        case "sheet":
207	            guard (value as? String) == "export" else { throw refuse("wait.sheet is not \"export\"") }
208	            return .sheetExport
209	        case "export_started":
210	            guard isTrue(value) else { throw refuse("wait.export_started is not true") }
211	            return .exportStarted
212	        case "playing":
213	            guard isTrue(value) else { throw refuse("wait.playing is not true") }
214	            return .playing
215	        default:
216	            throw refuse("wait has an unknown condition \(key)")
217	        }
218	    }
219	
220	    static func showMe(_ raw: Any) throws -> TutorialShowMe {
221	        guard let object = raw as? [String: Any] else { throw refuse("show_me is not an object") }
222	        if object["menu"] != nil {
223	            guard object.count == 1, let text = object["menu"] as? String else {
224	                throw refuse("a menu Show Me is exactly {\"menu\": \"A ▸ B\"}")
225	            }
226	            let path = text.components(separatedBy: "▸")
227	                .map { $0.trimmingCharacters(in: .whitespaces) }
228	            guard path.count >= 2, path.allSatisfy({ !$0.isEmpty }) else {
229	                throw refuse("a menu Show Me's path is not A ▸ B")
230	            }
231	            return .menu(path: path)
232	        }
233	        guard let name = object["tool"] as? String, !name.isEmpty,
234	              Set(object.keys).isSubset(of: ["tool", "args"])
235	        else { throw refuse("a tool Show Me is {tool, args?}") }
236	        var args: [String: Any] = [:]
237	        if let raw = object["args"] {
238	            guard let dict = raw as? [String: Any] else { throw refuse("args is not an object") }
239	            args = dict
240	        }
241	        try variables(args)
242	        return .tool(name: name, args: args)
243	    }
