262	    static func reference(_ value: Any) throws {
263	        if let text = value as? String, TutorialClipSet(rawValue: text) != nil { return }
264	        if let object = value as? [String: Any], object.count == 1,
265	           object["$pick"] != nil || object["$first"] != nil
266	        {
267	            return try variable(object)
268	        }
269	        throw refuse("a reference is not $selection, $created, a $pick or a $first")
270	    }
271	
272	    static func variable(_ object: [String: Any]) throws {
273	        guard object.count == 1, let (key, item) = object.first else {
274	            throw refuse("a variable object holds one key")
275	        }
276	        switch key {
277	        case "$pick":
278	            _ = try filter(item, "$pick")
279	        case "$first":
280	            guard let text = item as? String, TutorialClipSet(rawValue: text) != nil else {
281	                throw refuse("$first takes $selection or $created")
282	            }
283	        case "$track":
284	            guard (item as? String) == "front" else { throw refuse("$track takes \"front\"") }
285	        case "$time":
286	            guard let spec = item as? [String: Any], Set(spec.keys) == ["of", "at"],
287	                  let of = spec["of"]
288	            else { throw refuse("$time takes exactly {of, at}") }
289	            try reference(of)
290	            guard let at = spec["at"] as? String, ["start", "middle", "end"].contains(at) else {
291	                throw refuse("$time.at is not start, middle or end")
292	            }
293	        default:
294	            throw refuse("unknown variable \(key)")
295	        }
296	    }
297	}
