3	/// `TutorialLibrary.decode`'s per-tutorial half (spec §11 TU-8 (1)): TU-2's
4	/// vocabulary, one refusal sentence per breach, thrown as a
5	/// `TutorialModelError` that refuses that tutorial alone. Its own file for
6	/// the 400-line cap on new files; `TutorialModel.swift` holds the types.
7	enum TutorialDecoder {
8	    static let tutorialKeys: Set<String> = ["id", "title", "anchor", "needs", "steps"]
9	    static let stepKeys: Set<String> = ["text", "reveal", "spotlight", "wait", "show_me", "optional"]
10	    static let idPattern = "^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)+$"
11	    static let plainVariables: Set<String> = ["$selection", "$created", "$playhead"]
12	
13	    static func refuse(_ message: String) -> TutorialModelError {
14	        TutorialModelError(message: message)
15	    }
16	
17	    static func tutorial(_ raw: Any) throws -> Tutorial {
18	        guard let object = raw as? [String: Any] else { throw refuse("a tutorial is not an object") }
19	        if let stranger = object.keys.sorted().first(where: { !tutorialKeys.contains($0) }) {
20	            throw refuse("unknown tutorial key \(stranger)")
21	        }
22	        guard let id = object["id"] as? String,
23	              id.range(of: idPattern, options: .regularExpression) != nil
24	        else { throw refuse("the id is not dotted lowercase words") }
25	        guard let title = object["title"] as? String, let anchor = object["anchor"] as? String
26	        else { throw refuse("the tutorial has no title or anchor") }
27	        var needs: [String: Any]?
28	        if let raw = object["needs"] {
29	            guard let dict = raw as? [String: Any], Set(dict.keys).isSubset(of: ["clip"]) else {
30	                throw refuse("needs is {clip: <filter>}")
31	            }
32	            if let clip = dict["clip"] { needs = try filter(clip, "needs.clip") }
33	        }
34	        guard let rawSteps = object["steps"] as? [Any], !rawSteps.isEmpty else {
35	            throw refuse("the tutorial has no steps")
36	        }
37	        var steps: [TutorialStep] = []
38	        for (index, raw) in rawSteps.enumerated() {
39	            do {
40	                steps.append(try step(raw))
41	            } catch let error as TutorialModelError {
42	                throw refuse("step \(index + 1): \(error.message)")
43	            }
44	        }
45	        return Tutorial(id: id, title: title, anchor: anchor, needs: needs, steps: steps)
46	    }
