59	        var wait: [TutorialCondition] = []
60	        if let raw = object["wait"] { wait = try Self.wait(raw) }
61	        var showMe: [TutorialShowMe] = []
62	        if let raw = object["show_me"] {
63	            let entries = (raw as? [Any]) ?? [raw]
64	            guard !entries.isEmpty else { throw refuse("show_me is an empty list") }
65	            showMe = try entries.map(Self.showMe)
66	        }
