68	        if let raw = object["optional"] {
69	            guard TutorialJSON.isBool(raw), (raw as? Bool) == true else {
70	                throw refuse("optional is not true")
71	            }
72	            optional = true
73	        }
74	        return TutorialStep(
75	            text: text, reveal: reveal, spotlight: spotlight, wait: wait, showMe: showMe,
76	            optional: optional)
77	    }
