220	    static func showMe(_ raw: Any) throws -> TutorialShowMe {
221	        guard let object = raw as? [String: Any] else { throw refuse("show_me is not an object") }
222	        if object["menu"] != nil {
223	            guard object.count == 1, let text = object["menu"] as? String else {
224	                throw refuse("a menu Show Me is exactly {\"menu\": \"A ▸ B\"}")
225	            }
226	            let path = text.components(separatedBy: "▸")
227	                .map { $0.trimmingCharacters(in: .whitespaces) }
228	            guard path.count >= 2, path.allSatisfy({ !$0.isEmpty }) else {
229	                throw refuse("a menu Show Me's path is not A ▸ B")
230	            }
231	            return .menu(path: path)
232	        }
233	        guard let name = object["tool"] as? String, !name.isEmpty,
234	              Set(object.keys).isSubset(of: ["tool", "args"])
235	        else { throw refuse("a tool Show Me is {tool, args?}") }
236	        var args: [String: Any] = [:]
237	        if let raw = object["args"] {
238	            guard let dict = raw as? [String: Any] else { throw refuse("args is not an object") }
239	            args = dict
240	        }
241	        try variables(args)
242	        return .tool(name: name, args: args)
243	    }
244	
245	    /// Every `$`-string and `$`-key at any depth is one of TU-2 (9)'s.
246	    static func variables(_ value: Any) throws {
247	        if let text = value as? String {
248	            if text.hasPrefix("$"), !plainVariables.contains(text) {
249	                throw refuse("unknown variable \(text)")
250	            }
251	        } else if let list = value as? [Any] {
252	            try list.forEach(variables)
253	        } else if let object = value as? [String: Any] {
254	            if object.keys.contains(where: { $0.hasPrefix("$") }) {
255	                try variable(object)
256	            } else {
257	                try object.values.forEach(variables)
258	            }
259	        }
260	    }
261	
262	    static func reference(_ value: Any) throws {
263	        if let text = value as? String, TutorialClipSet(rawValue: text) != nil { return }
264	        if let object = value as? [String: Any], object.count == 1,
265	           object["$pick"] != nil || object["$first"] != nil
266	        {
267	            return try variable(object)
268	        }
269	        throw refuse("a reference is not $selection, $created, a $pick or a $first")
270	    }
271	
272	    static func variable(_ object: [String: Any]) throws {
273	        guard object.count == 1, let (key, item) = object.first else {
274	            throw refuse("a variable object holds one key")
275	        }
276	        switch key {
277	        case "$pick":
278	            _ = try filter(item, "$pick")
279	        case "$first":
280	            guard let text = item as? String, TutorialClipSet(rawValue: text) != nil else {
281	                throw refuse("$first takes $selection or $created")
282	            }
283	        case "$track":
284	            guard (item as? String) == "front" else { throw refuse("$track takes \"front\"") }
285	        case "$time":
286	            guard let spec = item as? [String: Any], Set(spec.keys) == ["of", "at"],
287	                  let of = spec["of"]
288	            else { throw refuse("$time takes exactly {of, at}") }
289	            try reference(of)
290	            guard let at = spec["at"] as? String, ["start", "middle", "end"].contains(at) else {
291	                throw refuse("$time.at is not start, middle or end")
292	            }
293	        default:
294	            throw refuse("unknown variable \(key)")
295	        }
296	    }
